import sys,psycopg2,pandas as pd,numpy as np
sys.path.insert(0,'/root/pe-queue/runner'); sys.path.insert(0,'/root/pe-queue/jobs'); import creds
L=psycopg2.connect(creds.pg_local()); L.autocommit=True; c=L.cursor(); c.execute("SET statement_timeout='400s'; SET work_mem='64MB'")
c.execute("""CREATE TEMP TABLE tk AS SELECT market_id,sel_id,extract(epoch from pt)::float8 t,tv::float8 tv FROM stream_ticks WHERE sport='racing' AND mkt='WIN' AND inplay AND tv IS NOT NULL""")
c.execute("CREATE INDEX ON tk (market_id,sel_id,t)"); c.execute("ANALYZE tk")
c.execute("SELECT min(t),max(t) FROM tk"); lo,hi=c.fetchone()
c.execute("""CREATE TEMP TABLE en AS SELECT market_id,sel::bigint sel_id,q,t::float8 t,px::float8 px,won,v::float8 v FROM finder_touch_entries WHERE q IN (1.1,1.2) AND d=1 AND side='back' AND t BETWEEN %s AND %s""",(lo,hi))
c.execute("""SELECT e.q,count(*),sum(CASE WHEN x.tvb IS NOT NULL AND x.tva<x.tvb*0.999 THEN 1 ELSE 0 END),sum(CASE WHEN x.tvb IS NOT NULL THEN 1 ELSE 0 END),avg(e.v) FROM en e LEFT JOIN LATERAL (SELECT max(tv) FILTER (WHERE y.t<e.t) tvb,min(tv) FILTER (WHERE y.t>=e.t AND y.t<=e.t+5) tva FROM tk y WHERE y.market_id=e.market_id AND y.sel_id=e.sel_id AND y.t BETWEEN e.t-120 AND e.t+5) x ON true GROUP BY 1 ORDER BY 1"""); print('stream entries: q, n, tv fell at the fill, n with tv before, mean v',c.fetchall())
rc=psycopg2.connect(creds.pg_railway(),sslmode='require'); rc.autocommit=True; k=rc.cursor(); k.execute("SET statement_timeout='200s'")
k.execute("SELECT mkt,count(*) FROM liq_sample WHERE ts>='2026-11-07 09:00' GROUP BY 1 ORDER BY 2 DESC LIMIT 6"); print(k.fetchall())
k.execute("""SELECT ip,count(*),sum((d<-0.001)::int),sum((d<-0.01)::int) FROM (SELECT minute IS NOT NULL AND minute>0 ip,total_matched::float8/NULLIF(max(total_matched::float8) OVER (PARTITION BY market_id,sel ORDER BY ts ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0)-1 d FROM liq_sample WHERE mkt=(SELECT mkt FROM liq_sample WHERE ts>='2026-11-07 09:00' GROUP BY 1 ORDER BY count(*) DESC LIMIT 1) AND ts>='2026-11-06 12:00' AND ts<'2026-11-07 12:00') x WHERE d IS NOT NULL GROUP BY 1"""); print('liq_sample busiest mkt 24 h: in-play?, rows, falling >0.1%, >1%',k.fetchall())
k.execute("""SELECT count(*),sum((d<-0.001)::int),sum((d<-0.01)::int) FROM (SELECT total_matched::float8/NULLIF(max(total_matched::float8) OVER (PARTITION BY market_id,sel_id ORDER BY ts ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0)-1 d FROM ip_tape WHERE sport='tennis' AND market_type='MATCH_ODDS' AND status='OPEN' AND ts>=now()-interval '36 hours') x WHERE d IS NOT NULL"""); print('ip_tape tennis 36 h OPEN',k.fetchone())
k.execute("""SELECT count(*),sum((d<-0.001)::int),sum((d<-0.01)::int) FROM (SELECT total_matched::float8/NULLIF(max(total_matched::float8) OVER (PARTITION BY market_id,sel_id ORDER BY ts ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0)-1 d FROM cricket_fav_tape WHERE inplay) x WHERE d IS NOT NULL"""); print('cricket_fav_tape in play',k.fetchone())
for tb,col in (('bf_tennis_log','captured_at'),):
    k.execute(f"""SELECT inplay,count(*),sum((d<-0.001)::int),sum((d<-0.01)::int) FROM (SELECT inplay,total_matched::float8/NULLIF(max(total_matched::float8) OVER (PARTITION BY market_id,selection_id ORDER BY {col} ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0)-1 d FROM {tb} WHERE {col}>=now()-interval '2 days') x WHERE d IS NOT NULL GROUP BY 1"""); print(tb,k.fetchall())
